import 'package:mocktail/mocktail.dart';

class Cat {
  String sound() => 'meow!';
}

class MockCat extends Mock implements Cat {}

void main() {
  final cat = MockCat();
  when(() => cat.sound()).thenReturn('meow');
  expect(cat.sound(), 'meow');
  verify(() => cat.sound()).called(1);
}
